infra.envs/prod/gw/main.tf:
terraform {
  backend "s3" {}
}
provider "aws" {
  assume_role {
    role_arn = "arn:aws:iam::111111111111:role/TerraformAdminRole"
  }
}
resource "aws_iam_role" "task" {
  name = "gw-task"
  path = "/system/ecs/"
  assume_role_policy = "{}"
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.task.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sqs:SendMessage", Resource = "*" }] })
}

